WITH joined AS (SELECT e.id, e.store_id, e.product_id, e.sale_date, e.units, e.revenue, s.region, s.sqft, s.store_name FROM store_sales e LEFT JOIN stores s ON e.store_id = s.id), with_windows AS (SELECT *, PERCENT_RANK() OVER (ORDER BY units DESC NULLS FIRST) AS units_percent_rank, LEAD(units, 2) OVER (PARTITION BY region ORDER BY sale_date, id) AS next_units, COUNT(sqft) OVER (PARTITION BY store_id) AS store_id_count_sqft FROM joined), with_dims AS (SELECT s.id, s.product_id, s.sale_date, s.units, s.revenue, s.sqft, s.next_units, p.launch_date, p.product_name FROM with_windows s LEFT JOIN products p ON s.product_id = p.id WHERE p.category = 'Fashion'), metrics AS (SELECT id, units, revenue, sqft, next_units, product_name, LEAD(revenue) OVER w_grp AS next_revenue, LEAD(next_units) OVER w_grp AS next_next_units, ROW_NUMBER() OVER w_grp AS event_seq, MIN(units) OVER (PARTITION BY product_id) AS product_id_min_units FROM with_dims WINDOW w_grp AS (PARTITION BY product_id ORDER BY next_units, id)), summary AS (SELECT CASE WHEN product_id_min_units >= 40 THEN 'LARGE' ELSE 'SMALL' END AS product_id_min_units_tier, CASE WHEN units >= 38 THEN 'LARGE' ELSE 'SMALL' END AS units_tier, STDDEV_SAMP(revenue) AS revenue_stddev, SUM(product_id_min_units) AS total_product_id_min_units, ROUND(AVG(revenue), 2) AS avg_revenue FROM metrics GROUP BY CASE WHEN product_id_min_units >= 40 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN units >= 38 THEN 'LARGE' ELSE 'SMALL' END HAVING STDDEV_SAMP(revenue) > 0) SELECT product_id_min_units_tier, units_tier, total_product_id_min_units FROM summary ORDER BY product_id_min_units_tier DESC NULLS LAST, total_product_id_min_units DESC;
